<?php function renderTable($headers,$rows,$module=''){ ?><div class="table-wrap"><table><thead><tr><?php foreach($headers as $h): ?><th><?=e($h)?></th><?php endforeach ?><th>Acções</th></tr></thead><tbody><?php foreach($rows as $i=>$row): ?><tr><?php foreach($row as $j=>$cell): ?><td><?php if($j===0): ?><span class="id-tag"><?=e($cell)?></span><?php elseif(preg_match('/Aberta|Activo|Concluído|Dentro/i',(string)$cell)): ?><span class="badge green"><?=e($cell)?></span><?php elseif(preg_match('/Pendente|andamento|Próximo/i',(string)$cell)): ?><span class="badge amber"><?=e($cell)?></span><?php elseif(preg_match('/Vencido|Cancelado|Encerrada/i',(string)$cell)): ?><span class="badge red"><?=e($cell)?></span><?php else: ?><?=e($cell)?><?php endif ?></td><?php endforeach ?><td><a class="action-link" href="/pages/<?=$module?>/detalhes.php?id=<?=$i+1?>">Ver</a><a class="action-link" href="/pages/<?=$module?>/editar.php?id=<?=$i+1?>">Editar</a></td></tr><?php endforeach ?></tbody></table></div><?php } ?>